    ir::Literal *Calculate(const ir::BinaryExpression *expr)
    {
        ES2PANDA_ASSERT(inputs_.size() == 2U);
        auto left = inputs_[0];
        auto right = inputs_[1];
        if (IsLogicalExpression(expr)) {
            return HandleLogicalExpression(expr, left, right);
