bool ETSChecker::ValidateResizableArrayDimension(ir::Expression *const expr, size_t const dimensionIndex)
{
    Type *expressionType = expr->Check(this);
    if (expressionType->IsTypeError()) {
        return false;
    }
    if (expr->IsAssignmentExpression()) {
        return false;
    }
    Type *const intType = GlobalIntBuiltinType();
    const auto assignCtx = AssignmentContext(
        Relation(), expr, expressionType, intType, expr->Start(),
        util::DiagnosticWithParams {diagnostic::TYPE_MISMATCH_AT_IDX, {expressionType, intType, dimensionIndex}});
    if (!assignCtx.IsAssignable()) {
        return false;
    }
    if (expressionType->IsETSEnumType()) {
        expr->AddAstNodeFlags(ir::AstNodeFlags::GENERATE_VALUE_OF);
    } else if (expressionType->IsETSObjectType() &&
               expressionType->AsETSObjectType()->HasObjectFlag(ETSObjectFlags::NUMERIC_ENUM_OBJECT)) {
        expr->AddAstNodeFlags(ir::AstNodeFlags::GENERATE_VALUE_OF);
    }
    if (!expressionType->IsConstantType() || !expr->IsNumberLiteral()) {
        return true;
    }
    ES2PANDA_ASSERT(expr->IsNumberLiteral());
    return ReportIfInvalidIntegralDimensionLiteral(this, expr, expressionType);
}

std::optional<std::size_t> ETSChecker::GetTupleElementAccessValue(const ir::Expression *expr)
{
    auto checkLongValBounds = [this](int64_t val, const lexer::SourcePosition &p) -> std::optional<size_t> {
        if (val < 0) {
            LogError(diagnostic::TUPLE_INDEX_OOB, {}, p);
            return std::nullopt;
        }
        return static_cast<size_t>(val);
    };

    if (expr->IsNumberLiteral()) {
        auto num = expr->AsNumberLiteral()->Number();
        if (num.IsByte()) {
            return checkLongValBounds(num.GetByte(), expr->Start());
        }
        if (num.IsShort()) {
            return checkLongValBounds(num.GetShort(), expr->Start());
        }
        if (num.IsInt()) {
            return checkLongValBounds(num.GetInt(), expr->Start());
        }
        if (num.IsLong()) {
            return checkLongValBounds(num.GetLong(), expr->Start());
        }
        ES2PANDA_UNREACHABLE();
    }

    // Below code should be unreachable after removing primitives
    // #29100: constantExpressionLowering may fail in some cases, and result in the `type` to be ETSObject.
    auto type = expr->TsType();

    ES2PANDA_ASSERT(type->HasTypeFlag(TypeFlag::CONSTANT | TypeFlag::ETS_CONVERTIBLE_TO_NUMERIC));

    switch (ETSType(type)) {
        case TypeFlag::BYTE: {
            return type->AsByteType()->GetValue();
        }
        case TypeFlag::SHORT: {
            return type->AsShortType()->GetValue();
        }
        case TypeFlag::INT: {
            return type->AsIntType()->GetValue();
        }
        case TypeFlag::LONG: {
            if (auto val = type->AsLongType()->GetValue();
                val <= std::numeric_limits<int32_t>::max() && val >= std::numeric_limits<int32_t>::min()) {
                return static_cast<std::size_t>(val);
            }
            return std::nullopt;
        }
        default: {
            return std::nullopt;
        }
    }
}

