ir::Literal *NodeCalculator::Calculate(DAGNode *node)
{
    switch (node->Ir()->Type()) {
        case ir::AstNodeType::IDENTIFIER:
        case ir::AstNodeType::MEMBER_EXPRESSION:
            return SubstituteConstant();
        case ir::AstNodeType::TS_AS_EXPRESSION:
